"""matplotlib._api.deprecation — deprecation decorators."""

import warnings

class MatplotlibDeprecationWarning(DeprecationWarning):
    """matplotlib's own deprecation warning subclass — separated from
    the stock DeprecationWarning so tests can opt-in/out independently."""


mplDeprecation = MatplotlibDeprecationWarning


def _format_deprecation_msg(since, name='', message='', alternative='',
                             obj_type='', addendum='', removal=''):
    """Build the deprecation message — matches upstream's wording."""
    obj_desc = f'The {obj_type} {name}' if obj_type else (name or 'This API')
    base = message or f'{obj_desc} is deprecated since {since}.'
    if removal:
        base += f' It will be removed in {removal}.'
    if alternative:
        base += f' Use {alternative} instead.'
    if addendum:
        base += f' {addendum}'
    return base


def warn_deprecated(since, *, message='', name='', alternative='',
                    pending=False, obj_type='', addendum='', removal=''):
    """Emit a MatplotlibDeprecationWarning with the standard wording."""
    msg = _format_deprecation_msg(since, name=name, message=message,
                                    alternative=alternative,
                                    obj_type=obj_type, addendum=addendum,
                                    removal=removal)
    category = (PendingDeprecationWarning if pending
                else MatplotlibDeprecationWarning)
    warnings.warn(msg, category, stacklevel=3)


def deprecated(since, *, message='', name='', alternative='',
               pending=False, obj_type='', addendum='', removal=''):
    """Mark a function/class/method as deprecated. The returned
    decorator wraps the target so a warning fires on first use —
    mirrors upstream's :func:`matplotlib._api.deprecated`."""

    def decorator(obj):
        nm = name or getattr(obj, '__name__', repr(obj))
        ot = obj_type or ('class' if isinstance(obj, type) else 'function')
        msg = _format_deprecation_msg(since, name=nm, message=message,
                                        alternative=alternative, obj_type=ot,
                                        addendum=addendum, removal=removal)
        if isinstance(obj, type):
            # Wrap __init__ so instantiating fires the warning.
            orig_init = obj.__init__
            def __init__(self, *args, **kwargs):
                warnings.warn(msg,
                               PendingDeprecationWarning if pending
                               else MatplotlibDeprecationWarning,
                               stacklevel=2)
                orig_init(self, *args, **kwargs)
            obj.__init__ = __init__
            return obj
        import functools
        @functools.wraps(obj)
        def _wrapper(*args, **kwargs):
            warnings.warn(msg,
                           PendingDeprecationWarning if pending
                           else MatplotlibDeprecationWarning,
                           stacklevel=2)
            return obj(*args, **kwargs)
        return _wrapper
    return decorator


def rename_parameter(since, old, new, func=None):
    """Decorator: accept ``old`` as an alias for ``new`` and warn."""
    def _decorator(fn):
        import functools
        @functools.wraps(fn)
        def _wrapper(*args, **kwargs):
            if old in kwargs:
                warnings.warn(
                    f'The {old!r} parameter of {fn.__name__}() has been renamed '
                    f'to {new!r} since {since}.',
                    MatplotlibDeprecationWarning, stacklevel=2)
                kwargs[new] = kwargs.pop(old)
            return fn(*args, **kwargs)
        return _wrapper
    return _decorator(func) if func is not None else _decorator


def delete_parameter(since, name, func=None, **kwargs):
    """Decorator: warn when ``name`` is passed (it's been removed)."""
    def _decorator(fn):
        import functools
        @functools.wraps(fn)
        def _wrapper(*args, **kw):
            if name in kw:
                warnings.warn(
                    f'The {name!r} parameter of {fn.__name__}() is deprecated '
                    f'since {since}.',
                    MatplotlibDeprecationWarning, stacklevel=2)
            return fn(*args, **kw)
        return _wrapper
    return _decorator(func) if func is not None else _decorator


def make_keyword_only(since, name, func=None):
    """Decorator: warn when ``name`` is still passed positionally
    (it's been moved to keyword-only)."""
    def _decorator(fn):
        import inspect, functools
        try:
            sig = inspect.signature(fn)
            pos_names = [p.name for p in sig.parameters.values()
                          if p.kind in (p.POSITIONAL_OR_KEYWORD,
                                          p.POSITIONAL_ONLY)]
            cutoff = pos_names.index(name) if name in pos_names else -1
        except (ValueError, TypeError):
            cutoff = -1
        @functools.wraps(fn)
        def _wrapper(*args, **kwargs):
            if cutoff >= 0 and len(args) > cutoff:
                warnings.warn(
                    f'Passing {name!r} positionally to {fn.__name__}() is '
                    f'deprecated since {since}; use it as a keyword argument.',
                    MatplotlibDeprecationWarning, stacklevel=2)
            return fn(*args, **kwargs)
        return _wrapper
    return _decorator(func) if func is not None else _decorator


