import contextlib


# Upstream tracks every decorator's deprecation metadata in this list so
# tooling can introspect what's been deprecated. The shim registers
# nothing (none of the no-op decorators above push to it) but exposes
# the symbol.
DECORATORS = []


def deprecate_method_override(method, obj, *, allow_empty=False, **kwargs):
    """No-op: upstream uses this to mark a subclass method as deprecated
    when it overrides a base-class method. Since the shim's decorators
    do nothing, this just returns the method unchanged."""
    return method


def deprecate_privatize_attribute(since, *, name=None, addendum=''):
    """Class decorator that marks a public attribute as deprecated in
    favour of a private one (e.g. ``self.foo`` → ``self._foo``). The
    shim wraps the attribute in a property that just reads the private
    name; no deprecation warning fires."""

    def _apply(cls):
        for attr in (name,) if name else ():
            priv = '_' + attr.lstrip('_')
            def _get(self, _p=priv): return getattr(self, _p, None)
            def _set(self, v, _p=priv): setattr(self, _p, v)
            setattr(cls, attr, property(_get, _set))
        return cls

    return _apply


@contextlib.contextmanager
def suppress_matplotlib_deprecation_warning():
    """Context manager that silences MatplotlibDeprecationWarning for
    the duration of the with-block. Mirrors the upstream helper used
    in tests that knowingly invoke deprecated APIs."""
    with warnings.catch_warnings():
        warnings.simplefilter('ignore', MatplotlibDeprecationWarning)
        yield
